// Validate incoming navigation request
const data = items[0].json;

const required = ['origin', 'destination'];
const missing = required.filter(k => !data[k]);
if (missing.length > 0) {
  return [{ json: { error: 'Missing required fields: ' + missing.join(', '), status: 'error' } }];
}

// Validate origin/destination have lat/lng
const forLoc = ['origin', 'destination'];
for (const loc of forLoc) {
  if (typeof data[loc].lat !== 'number' || typeof data[loc].lng !== 'number') {
    return [{ json: { error: loc + ' must have numeric lat and lng', status: 'error' } }];
  }
}

// Generate session ID
const sessionId = 'nav_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);

return [{
  json: {
    session_id: sessionId,
    origin: data.origin,
    destination: data.destination,
    destination_name: data.destination.name || data.destination.address || 'Destination',
    status: 'active',
    created_at: Date.now(),
    updated_at: Date.now(),
  }
}];

// Parse Google Routes API v2 response and extract route steps
const data = items[0].json;

// Handle API errors
if (data.error) {
  return [{
    json: {
      error: 'Routes API error: ' + (data.error.message || JSON.stringify(data.error)),
      status: 'failed',
      has_route: false,
    }
  }];
}

const routes = data.routes || [];
if (routes.length === 0) {
  return [{
    json: {
      error: 'No routes found for this origin/destination',
      status: 'failed',
      has_route: false,
    }
  }];
}

// Take first (best) route
const route = routes[0];

function parseDuration(raw) {
  if (!raw) return 0;
  raw = String(raw).trim();
  // Handle "Ns" format
  const secMatch = raw.match(/^(\d+)s$/);
  if (secMatch) return parseInt(secMatch[1], 10);
  // Handle ISO 8601 duration: PT3M, PT1H30M, PT45S
  const isoMatch = raw.match(/^PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/);
  if (isoMatch) {
    const h = parseInt(isoMatch[1] || 0, 10);
    const m = parseInt(isoMatch[2] || 0, 10);
    const s = parseInt(isoMatch[3] || 0, 10);
    return h * 3600 + m * 60 + s;
  }
  // Fallback: extract any number
  const numMatch = raw.match(/(\d+)/);
  return numMatch ? parseInt(numMatch[1], 10) : 0;
}

function extractLatLng(loc) {
  if (!loc) return { lat: 0, lng: 0 };
  const ll = loc.latLng || {};
  return { lat: ll.latitude || 0, lng: ll.longitude || 0 };
}

const legs = route.legs || [];
if (legs.length === 0) {
  return [{
    json: { error: 'Route has no legs', status: 'failed', has_route: false }
  }];
}

const leg = legs[0];
const rawSteps = leg.steps || [];

const steps = rawSteps.map((step, i) => {
  const nav = step.navigationInstruction || {};
  let maneuver = 'straight';
  const m = (nav.maneuver || '').toUpperCase();
  if (m.includes('LEFT')) maneuver = 'left';
  else if (m.includes('RIGHT')) maneuver = 'right';
  else if (m === 'UTURN_LEFT' || m === 'UTURN_RIGHT') maneuver = 'u-turn';
  else if (m === 'DESTINATION') maneuver = 'destination';
  else if (m.includes('SLIGHT')) maneuver = m.includes('LEFT') ? 'slightly_left' : 'slightly_right';
  else if (m === 'STRAIGHT') maneuver = 'straight';

  return {
    instruction: nav.instructions || 'Continue',
    distance_m: step.distanceMeters || 0,
    duration_s: parseDuration(step.duration),
    turn: maneuver,
    step_number: i,
    start_location: extractLatLng(step.startLocation),
    end_location: extractLatLng(step.endLocation),
  };
});

return [{
  json: {
    has_route: true,
    total_distance_m: route.distanceMeters || 0,
    total_duration_s: parseDuration(route.duration),
    steps: steps,
    current_step_index: 0,
    polyline: (route.polyline || {}).encodedPolyline || null,
    warnings: route.warnings || [],
    status: 'active',
    start_location: extractLatLng(leg.startLocation),
    end_location: extractLatLng(leg.endLocation),
  }
}];
